spec.usage_example:
// app.config.ts
export const appConfig: ApplicationConfig = { providers: [provideHttpClient()] };
// Host standalone: imports: [ClusterDashboardComponent]
// Template host: <dl-cluster-dashboard />

values := []int{1, 2, 2, 2, 9}
index, found := FirstIndex(values, 2) // index = 1; found = true
missing, ok := FirstIndex(values, 7) // missing = -1; ok = false

let dispatcher = SystemDispatcher::new(2);
let worker = dispatcher.dispatch(|| println!("tarefa")).expect("slot disponível");
worker.join().expect("worker sem panic");
assert_eq!(dispatcher.active_load(), 0);

const payload: unknown = JSON.parse('{"requestId":"abc","retries":0}');
assertType(payload, isGatewayPayload, 'Payload inválido');
// Só use payload.requestId após a validação real do predicado.
